-- =====================================================================
--  FLEMAN - full India seed data
--
--  Run ONCE on a fresh database, AFTER starting the backend so Hibernate
--  has created the tables:
--      mysql -u root -p fleetmanagement < seed-data-full-india.sql
--
--  Every seeded staff / customer password is: Password@123
-- =====================================================================

SET NAMES utf8mb4;
SET SQL_SAFE_UPDATES = 0;
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM invoice_detail;
DELETE FROM invoice_header;
DELETE FROM booking_detail;
DELETE FROM booking_header;
DELETE FROM car;
DELETE FROM addon;
DELETE FROM car_type;
DELETE FROM airport;
DELETE FROM staff;
DELETE FROM customer;
DELETE FROM hub;
DELETE FROM city;
DELETE FROM state;

ALTER TABLE car_type       AUTO_INCREMENT = 1;
ALTER TABLE addon          AUTO_INCREMENT = 1;
ALTER TABLE car            AUTO_INCREMENT = 1;
ALTER TABLE staff          AUTO_INCREMENT = 1;
ALTER TABLE booking_detail AUTO_INCREMENT = 1;

SET FOREIGN_KEY_CHECKS = 1;

-- state: 34 rows

-- city: 82 rows

-- hub: 290 rows

-- airport: 82 rows

-- staff: 290 rows

-- addon: 1137 rows

-- car_type: 1450 rows

-- car: 8926 rows

-- customer: 10 rows

SET SQL_SAFE_UPDATES = 1;

SELECT 'state' t, COUNT(*) n FROM state
UNION ALL SELECT 'city', COUNT(*) FROM city
UNION ALL SELECT 'airport', COUNT(*) FROM airport
UNION ALL SELECT 'hub', COUNT(*) FROM hub
UNION ALL SELECT 'staff', COUNT(*) FROM staff
UNION ALL SELECT 'addon', COUNT(*) FROM addon
UNION ALL SELECT 'car_type', COUNT(*) FROM car_type
UNION ALL SELECT 'car', COUNT(*) FROM car
UNION ALL SELECT 'customer', COUNT(*) FROM customer;
